// Источник: web-тест .qa/e2e/tests/zmanim/zm-02-dates-location-daily-study.spec.ts, план .qa/e2e/specs/zmanim.md, кейс .qa/tests/zmanim/ZM-02-dates-and-location.md
// Тикет #6a86f7df. В web часы фиксировались на 3.10.2026 (page.clock) — на устройстве «ТОЛЬКО СЕГОДНЯ»:
// ожидаемые даты вычисляются от реальной сегодняшней даты в формате приложения («כ״ב תשרי תשפ״ז», «3 באוקטובר»).
// Переход через границу месяца (3 × «היום הקודם» с 3-го числа) гарантирован только в первые 3 дня месяца — в остальные дни проверяется сдвиг на 3 дня.
import { expect } from '@wdio/globals';
import { byText, byTextContains, tapLabel, scrollToText, expectTextContains } from '../../helpers/ui.ts';
import { hasDeepLinks, openRoute } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

// ——— даты в формате приложения (как .qa/e2e/tests/_helpers/dates.ts) ———
const ONES = ['', 'א', 'ב', 'ג', 'ד', 'ה', 'ו', 'ז', 'ח', 'ט'];
const TENS = ['', 'י', 'כ', 'ל', 'מ', 'נ', 'ס', 'ע', 'פ', 'צ'];
const HUNDREDS = ['', 'ק', 'ר', 'ש', 'ת', 'תק', 'תר', 'תש', 'תת', 'תתק'];
const MONTH_FIX: Record<string, string> = { 'חשוון': 'חשון', 'סיוון': 'סיון' };
const GREG = ['ינואר', 'פברואר', 'מרץ', 'אפריל', 'מאי', 'יוני', 'יולי', 'אוגוסט', 'ספטמבר', 'אוקטובר', 'נובמבר', 'דצמבר'];
function gematria(n: number): string {
  let s = HUNDREDS[Math.floor(n / 100)];
  const rest = n % 100;
  if (rest === 15) s += 'טו';
  else if (rest === 16) s += 'טז';
  else s += TENS[Math.floor(rest / 10)] + ONES[rest % 10];
  return s.length === 1 ? `${s}׳` : `${s.slice(0, -1)}״${s.slice(-1)}`;
}
function hebrewDate(d: Date): string {
  const parts = new Intl.DateTimeFormat('he-u-ca-hebrew-nu-latn', { day: 'numeric', month: 'long', year: 'numeric' }).formatToParts(d);
  const get = (t: string) => parts.find((p) => p.type === t)?.value ?? '';
  const month = MONTH_FIX[get('month')] ?? get('month');
  return `${gematria(Number(get('day')))} ${month} ${gematria(Number(get('year')) % 1000)}`;
}
const gregDay = (d: Date) => `${d.getDate()} ב${GREG[d.getMonth()]}`;
const noonShift = (d: Date, days: number, years = 0) => new Date(d.getFullYear() + years, d.getMonth(), d.getDate() + days, 12);

/** Экран «זמני היום»: deep link (APP_SCHEME), иначе — с главной по ссылке/карточке (название уточнить на устройстве). */
async function openZmanim() {
  if (hasDeepLinks()) await openRoute('/zmanim');
  else {
    await toHome();
    for (const name of ['זמני היום', 'זמני התפילות', 'זמנים']) {
      const el = await scrollToText(name, 6).catch(() => null);
      if (el) { await el.click(); break; }
    }
  }
  await (await byTextContains('שקיעת החמה')).waitForDisplayed({ timeout: 25000 });
}

async function expectDate(d: Date) {
  await (await byText(gregDay(d))).waitForDisplayed({ timeout: 15000, timeoutMsg: `нет даты ${gregDay(d)}` });
  await expect(byText(String(d.getFullYear()))).toBeDisplayed();
  await expect(byText(hebrewDate(d))).toBeDisplayed();
}

describe('זמני היום', () => {
  afterEach(async () => { await toHome(); });

  it('ZM-02 Даты (сегодня), навигация по дням и годам, место расчёта, ежедневное изучение #6a86f7df @prod-safe', async () => {
    const today = noonShift(new Date(), 0);

    // 1. Верх экрана — сегодняшние еврейская и григорианская даты, год.
    await openZmanim();
    await expectDate(today);

    // 2. «היום הקודם» × 3 → дата − 3 дня.
    for (let i = 0; i < 3; i++) await tapLabel('היום הקודם');
    const minus3 = noonShift(today, -3);
    await expectDate(minus3);

    // 3. «השנה הבאה» → та же дата через год.
    await tapLabel('השנה הבאה');
    await expectDate(noonShift(minus3, 0, 1));

    // 4. «השנה הקודמת» → снова дата − 3 дня.
    await tapLabel('השנה הקודמת');
    await expectDate(minus3);

    // Строка места расчёта (город профиля user1).
    await scrollToText('הזמנים חושבו עבור');
    await expectTextContains('הזמנים חושבו עבור פתח תקווה, לפי השעון המקומי שם.');

    // 5. «לימוד יומי»: три строки с непустым значением.
    for (const label of ['דף יומי בבלי', 'דף יומי ירושלמי', 'עמוד יומי במשנה ברורה']) {
      const el = await scrollToText(label);
      await expect(el).toBeDisplayed();
    }

    // Источник и примечание.
    await scrollToText('Hebcal.com');
    await expect(byTextContains('Hebcal.com')).toBeDisplayed();
    await scrollToText('טרם אושרו על ידי גורם הלכתי מוסמך');
    await expect(byTextContains('טרם אושרו על ידי גורם הלכתי מוסמך')).toBeDisplayed();
  });
});
